WITH cleaned AS (SELECT *, ROUND(temp_c, 2) temp_c_rounded FROM device_readings WHERE reading_ts > DATE '2025-09-01') SELECT CASE WHEN pressure >= 1029 THEN 'HIGH' ELSE 'LOW' END AS pressure_tier, CASE WHEN humidity >= 73 THEN 'PREMIUM' ELSE 'STANDARD' END AS humidity_tier, SUM(CASE WHEN device_code = 'DV-01' THEN temp_c_rounded ELSE 0 END) AS dv_01_temp_c_rounded, STDDEV_SAMP(pressure) AS pressure_stddev, COUNT(*) AS num_rows FROM cleaned GROUP BY CASE WHEN pressure >= 1029 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN humidity >= 73 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY pressure_stddev;
